-- Instrument 8: Strategic Recommendations & 90-Day Roadmap
UPDATE assessment_template_versions tv
SET schema_definition=$schema${"instrument_number":8,"template_name":"Strategic Recommendations & 90-Day Roadmap","description":"An advisor-led recommendation and execution-design instrument that converts validated diagnoses and ranked opportunities into an owner-aligned strategic direction, sequenced initiatives, a practical 30/60/90-day roadmap and measurable governance.","schema_status":"active","sections":[{"id":"strategic_direction","title":"1. Strategic direction & recommendation principles","description":"Translate the diagnosis and opportunity ranking into a coherent, owner-approved direction.","questions":[{"key":"rec_strategy","label":"Strategic direction and intended business outcomes","type":"textarea","required":true},{"key":"rec_objectives","label":"Strategic objectives for the engagement horizon","type":"textarea","required":true},{"key":"rec_value_logic","label":"Value-creation logic and causal link to diagnosed issues","type":"textarea","required":true},{"key":"rec_guardrails","label":"Non-negotiable constraints, values and risk guardrails","type":"textarea","required":false},{"key":"rec_tradeoffs","label":"Strategic trade-offs and what the business should stop or deprioritize","type":"textarea","required":true},{"key":"rec_owner_alignment","label":"Owner / leadership alignment and unresolved disagreements","type":"textarea","required":false},{"key":"rec_decision_principles","label":"Decision principles for sequencing initiatives","type":"textarea","required":true}]},{"id":"recommendation_1","title":"2. Strategic recommendation 1","description":"Define one actionable recommendation linked to a diagnosed cause and prioritized opportunity. Keep expected results tied to evidence and explicit assumptions.","questions":[{"key":"r1_name","label":"Recommendation / initiative name","type":"text","required":true},{"key":"r1_linked_opportunity","label":"Linked Instrument 7 opportunity and priority score","type":"text","required":true},{"key":"r1_problem","label":"Problem or root cause addressed","type":"textarea","required":true},{"key":"r1_action","label":"Recommended change and scope","type":"textarea","required":true},{"key":"r1_rationale","label":"Evidence, strategic rationale and alternatives considered","type":"textarea","required":true},{"key":"r1_outcome","label":"Expected outcome and measurable success indicators","type":"textarea","required":true},{"key":"r1_owner","label":"Accountable executive / initiative owner","type":"text","required":true},{"key":"r1_resources","label":"Required people, capabilities, budget and technology","type":"textarea","required":false},{"key":"r1_dependencies","label":"Dependencies, prerequisites and sequencing","type":"textarea","required":false},{"key":"r1_risks","label":"Risks, mitigations and customer / employee impacts","type":"textarea","required":false},{"key":"r1_timing","label":"Recommended timing","type":"select","required":false,"options":["0–30 days","31–60 days","61–90 days","Beyond 90 days","Ongoing"]},{"key":"r1_decision_gate","label":"Decision gate and evidence required to proceed","type":"textarea","required":false}]},{"id":"recommendation_2","title":"3. Strategic recommendation 2","description":"Define one actionable recommendation linked to a diagnosed cause and prioritized opportunity. Keep expected results tied to evidence and explicit assumptions.","questions":[{"key":"r2_name","label":"Recommendation / initiative name","type":"text","required":false},{"key":"r2_linked_opportunity","label":"Linked Instrument 7 opportunity and priority score","type":"text","required":false},{"key":"r2_problem","label":"Problem or root cause addressed","type":"textarea","required":false},{"key":"r2_action","label":"Recommended change and scope","type":"textarea","required":false},{"key":"r2_rationale","label":"Evidence, strategic rationale and alternatives considered","type":"textarea","required":false},{"key":"r2_outcome","label":"Expected outcome and measurable success indicators","type":"textarea","required":false},{"key":"r2_owner","label":"Accountable executive / initiative owner","type":"text","required":false},{"key":"r2_resources","label":"Required people, capabilities, budget and technology","type":"textarea","required":false},{"key":"r2_dependencies","label":"Dependencies, prerequisites and sequencing","type":"textarea","required":false},{"key":"r2_risks","label":"Risks, mitigations and customer / employee impacts","type":"textarea","required":false},{"key":"r2_timing","label":"Recommended timing","type":"select","required":false,"options":["0–30 days","31–60 days","61–90 days","Beyond 90 days","Ongoing"]},{"key":"r2_decision_gate","label":"Decision gate and evidence required to proceed","type":"textarea","required":false}]},{"id":"recommendation_3","title":"4. Strategic recommendation 3","description":"Define one actionable recommendation linked to a diagnosed cause and prioritized opportunity. Keep expected results tied to evidence and explicit assumptions.","questions":[{"key":"r3_name","label":"Recommendation / initiative name","type":"text","required":false},{"key":"r3_linked_opportunity","label":"Linked Instrument 7 opportunity and priority score","type":"text","required":false},{"key":"r3_problem","label":"Problem or root cause addressed","type":"textarea","required":false},{"key":"r3_action","label":"Recommended change and scope","type":"textarea","required":false},{"key":"r3_rationale","label":"Evidence, strategic rationale and alternatives considered","type":"textarea","required":false},{"key":"r3_outcome","label":"Expected outcome and measurable success indicators","type":"textarea","required":false},{"key":"r3_owner","label":"Accountable executive / initiative owner","type":"text","required":false},{"key":"r3_resources","label":"Required people, capabilities, budget and technology","type":"textarea","required":false},{"key":"r3_dependencies","label":"Dependencies, prerequisites and sequencing","type":"textarea","required":false},{"key":"r3_risks","label":"Risks, mitigations and customer / employee impacts","type":"textarea","required":false},{"key":"r3_timing","label":"Recommended timing","type":"select","required":false,"options":["0–30 days","31–60 days","61–90 days","Beyond 90 days","Ongoing"]},{"key":"r3_decision_gate","label":"Decision gate and evidence required to proceed","type":"textarea","required":false}]},{"id":"roadmap_30","title":"5. First 30 days — stabilize, validate & mobilize","description":"Specify the first actions that create control, validate assumptions and prepare execution.","questions":[{"key":"r30_objective","label":"30-day objectives","type":"textarea","required":true},{"key":"r30_actions","label":"Prioritized actions and work packages","type":"textarea","required":true},{"key":"r30_deliverables","label":"Expected deliverables and acceptance criteria","type":"textarea","required":true},{"key":"r30_owner","label":"Accountable owner(s)","type":"text","required":true},{"key":"r30_measures","label":"Leading indicators and baseline measures","type":"textarea","required":true},{"key":"r30_dependencies","label":"Dependencies, resources and decision gates","type":"textarea","required":false},{"key":"r30_risks","label":"Risks, customer / employee impacts and mitigations","type":"textarea","required":false},{"key":"r30_gate","label":"Day-30 review and go / adjust / stop decisions","type":"textarea","required":true}]},{"id":"roadmap_60","title":"6. Days 31–60 — implement priority changes","description":"Move from mobilization into controlled implementation and early outcome validation.","questions":[{"key":"r60_objective","label":"60-day objectives","type":"textarea","required":true},{"key":"r60_actions","label":"Prioritized actions and work packages","type":"textarea","required":true},{"key":"r60_deliverables","label":"Expected deliverables and acceptance criteria","type":"textarea","required":true},{"key":"r60_owner","label":"Accountable owner(s)","type":"text","required":true},{"key":"r60_measures","label":"Leading indicators and outcome measures","type":"textarea","required":true},{"key":"r60_dependencies","label":"Dependencies, resources and decision gates","type":"textarea","required":false},{"key":"r60_risks","label":"Risks, customer / employee impacts and mitigations","type":"textarea","required":false},{"key":"r60_gate","label":"Day-60 review and go / adjust / stop decisions","type":"textarea","required":true}]},{"id":"roadmap_90","title":"7. Days 61–90 — embed, measure & scale","description":"Institutionalize successful changes, measure realized outcomes and determine the next horizon.","questions":[{"key":"r90_objective","label":"90-day objectives","type":"textarea","required":true},{"key":"r90_actions","label":"Prioritized actions and work packages","type":"textarea","required":true},{"key":"r90_deliverables","label":"Expected deliverables and acceptance criteria","type":"textarea","required":true},{"key":"r90_owner","label":"Accountable owner(s)","type":"text","required":true},{"key":"r90_measures","label":"Outcome measures, benefits tracking and baseline comparison","type":"textarea","required":true},{"key":"r90_dependencies","label":"Dependencies, resources and decision gates","type":"textarea","required":false},{"key":"r90_risks","label":"Risks, customer / employee impacts and mitigations","type":"textarea","required":false},{"key":"r90_gate","label":"Day-90 review, benefits validation and next-horizon decisions","type":"textarea","required":true}]},{"id":"governance","title":"8. Governance, benefits realization & executive handoff","description":"Establish decision rights, monitoring cadence and how benefits will be validated.","questions":[{"key":"rec_governance","label":"Governance, decision rights and escalation path","type":"textarea","required":true},{"key":"rec_cadence","label":"Review cadence, meeting owners and reporting format","type":"textarea","required":true},{"key":"rec_benefits","label":"Benefits realization plan and attribution approach","type":"textarea","required":true},{"key":"rec_baseline","label":"Baseline, KPI definitions, data sources and measurement owner","type":"textarea","required":true},{"key":"rec_change","label":"Change management, communication, training and adoption","type":"textarea","required":false},{"key":"rec_capacity","label":"Management capacity and external support requirements","type":"textarea","required":false},{"key":"rec_exit","label":"Advisor handoff, management ownership and exit criteria","type":"textarea","required":true},{"key":"rec_confidence","label":"Advisor confidence in recommendations and roadmap","type":"select","required":true,"options":["High — evidence-supported, feasible and owner-aligned","Moderate — sound direction with material assumptions","Low — preliminary; validation and owner decisions remain","Insufficient — defer implementation commitment"]}]}],"assessment_policy":"Recommendations must trace to evidence and the root-cause analysis. Priority scores and scenario estimates from Instrument 7 are decision aids, not guarantees. Distinguish expected outcomes from committed targets and realized benefits. Assign accountable owners, decision rights, prerequisites, capacity, risks and customer/employee impacts. Do not promise savings, revenue, valuation or investment returns without validated baselines and assumptions. The advisor recommends and monitors; management owns execution and the owner retains decision authority."}$schema$::jsonb,
 scoring_definition=$score${"rating_owner":"advisor","missing_data_policy":"Unknown baselines and unvalidated benefits remain explicitly unknown.","traceability":"Every recommendation must link to an Instrument 6 diagnosis and, where applicable, an Instrument 7 opportunity.","execution_policy":"Management owns execution; advisor recommends, facilitates and monitors. Owner retains decision authority.","benefits_policy":"Separate expected benefits, approved targets and realized outcomes. Do not guarantee scenario estimates."}$score$::jsonb,
 published_at=COALESCE(tv.published_at,now())
FROM assessment_templates t
WHERE tv.template_id=t.id AND t.instrument_number=8 AND tv.version_number=t.current_version;
